def evaluate(left, operator, right):
    if operator == '+':
        return left + right
    elif operator == '-':
        return left - right
    elif operator == '*':
        return left * right
    elif operator == '/':
        return left // right
    elif operator == '^':
        return left ** right
    elif operator == '%':
        return left % right

