def create_anagram(s, t):
    from collections import Counter

    count_s = Counter(s)
    count_t = Counter(t)

    replacements = 0
    for char, freq in count_t.items():
        if count_s[char] < freq:
            replacements += freq - count_s[char]

    return replacements
